const elasticCards=[...document.querySelectorAll('[data-elastic-card]')];function expandInstitution(index){elasticCards.forEach((card,i)=>{const active=i===index;card.classList.toggle('is-active',active);const trigger=card.querySelector('.elastic-trigger');trigger.setAttribute('aria-expanded',String(active));trigger.querySelector('span').textContent=active?'−':'+'})}elasticCards.forEach((card,index)=>{card.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse')expandInstitution(index)});card.addEventListener('focusin',()=>expandInstitution(index));card.querySelector('.elastic-trigger').addEventListener('click',()=>expandInstitution(index));card.addEventListener('click',event=>{if(!event.target.closest('a'))expandInstitution(index)});card.addEventListener('keydown',event=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(event.key)){event.preventDefault();let next=event.key==='Home'?0:event.key==='End'?2:(index+(['ArrowRight','ArrowDown'].includes(event.key)?1:2))%3;expandInstitution(next);elasticCards[next].querySelector('.elastic-trigger').focus()}})});
